'use strict';
const C=window.SITE_CONFIG, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-2-1-6-2-10 1zM12 5v15"/>',test:'<rect x="5" y="4" width="15" height="18" rx="2"/><path d="M9 2h7v4H9zM9 10h7M9 14h7M9 18h4"/>',chart:'<path d="M3 3v18h18M7 16l5-6 4 3 5-7"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-2 9 6-3 6 3-2-9M10 8l1 1 3-3"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',admin:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>'};
const ico=n=>`<span class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[n]||icons.book}</svg></span>`;
const art=()=>`<svg viewBox="0 0 300 280" role="img" aria-label="Livros formando uma escada até uma estrela"><circle cx="145" cy="145" r="107" fill="#365c4b"/><circle cx="145" cy="145" r="84" fill="none" stroke="#78937b" stroke-dasharray="3 9"/><path d="M47 218h73v-23h47v-32h48v-35h43" fill="none" stroke="#7c9878" stroke-width="2" stroke-dasharray="5 5"/><g transform="rotate(-9 115 201)"><rect x="40" y="209" width="119" height="25" rx="4" fill="#95b382"/><path d="M50 213h106v16H50" fill="#e9efda"/><rect x="50" y="179" width="123" height="27" rx="4" fill="#c6d9a4"/><path d="M61 185h107v15H61" fill="#f4f6e9"/><rect x="74" y="145" width="125" height="30" rx="4" fill="#e2b993"/><path d="M85 152h108v16H85" fill="#fbefdf"/><rect x="103" y="113" width="124" height="27" rx="4" fill="#c9bed9"/><path d="M114 119h107v15H114" fill="#f3eef7"/></g><path d="m228 43 9 20 22 3-16 15 4 22-19-10-19 10 4-22-16-15 22-3z" fill="#d8ebb9"/><path d="m70 72 4 9 10 2-8 7 2 10-8-5-9 5 2-10-7-7 10-2z" fill="#b5c6a2"/><path d="M260 126v10m-5-5h10M55 130v10m-5-5h10" stroke="#93b08b" stroke-width="2"/></svg>`;
const brand=()=>'<a href="#" class="brand" data-action="home"><img src="icon.svg" alt=""><span>Missão Tiradentes<small>Seu próximo passo</small></span></a>';
let course={topics:[],questions:[],exams:[]},user=null,session=null,demo=false,page='dashboard',subject='Todos',query='',quiz=null,exam=null,results=null,timer=null,adminDemo='pending';
const emptyState=()=>({history:[],lessons:[],checks:[],rewards:[]});
let state=emptyState();
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function persist(){if(demo)localStorage.setItem('tiradentes-demo-v1',JSON.stringify(state));}
function flash(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(flash.t);flash.t=setTimeout(()=>$('#toast').style.display='none',4200)}
function today(){return new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}
function topic(id){return course.topics.find(t=>t.id===id)}
function evidence(){const m=new Map();for(const h of [...state.history].reverse())for(const a of h.items||[])if(!a.annulled&&!m.has(a.id))m.set(a.id,a);return [...m.values()]}
function metrics(id){let v=evidence().filter(a=>a.topic===id);return {n:v.length,correct:v.filter(a=>a.correct).length,rate:v.length?Math.round(v.filter(a=>a.correct).length/v.length*100):null,uncertain:v.some(a=>a.confidence==='guess')}}
function status(id){const m=metrics(id);return m.n===0?'Ainda não avaliado':m.n<3?(m.rate<70?'Reforçar · poucos dados':'Bom começo · poucos dados'):m.rate>=80?'Consolidando':m.rate<60?'Prioridade de revisão':'Em desenvolvimento'}
function priorities(){return [...course.topics].sort((a,b)=>{const x=metrics(a.id),y=metrics(b.id);const p=m=>m.n?m.rate+(m.uncertain?-10:0):50;return p(x)-p(y)})}
function earnedAnswers(){return [...new Map(state.history.flatMap(h=>h.items||[]).filter(a=>a.correct&&!a.annulled).map(a=>[a.id,a])).values()]}
function xp(){const good=new Set(earnedAnswers().map(a=>a.id));const recovery=new Set();for(const h of state.history)for(const a of h.items||[])if(a.correct&&!a.annulled&&state.history.some(old=>old.date<h.date&&(old.items||[]).some(x=>x.id===a.id&&!x.correct)))recovery.add(a.topic);return good.size*10+state.lessons.length*15+recovery.size*20+new Set(state.history.filter(h=>h.kind==='exam'&&h.items.every(a=>a.selected!==null)).map(h=>h.label)).size*50}
function achievements(){const wins=earnedAnswers();const days=new Set(state.history.map(h=>h.date.slice(0,10)));const recovery=state.history.some(h=>(h.items||[]).some(a=>a.correct&&state.history.some(old=>old.date<h.date&&(old.items||[]).some(x=>x.id===a.id&&!x.correct))));return [{id:'start',title:'Primeiro passo',desc:'Conclua seu primeiro diagnóstico.',ok:state.history.some(h=>h.kind==='diagnostic'),icon:'compass'},{id:'reader',title:'Mente curiosa',desc:'Estude e pratique três aulas diferentes.',ok:state.lessons.length>=3,icon:'book'},{id:'recovery',title:'Virada de jogo',desc:'Acerte uma questão que você havia errado.',ok:recovery,icon:'spark'},{id:'exam',title:'Missão completa',desc:'Finalize uma prova anterior inteira.',ok:state.history.some(h=>h.kind==='exam'&&h.items.filter(a=>a.selected!==null).length===50),icon:'test'},{id:'steady',title:'Constância',desc:'Pratique em três dias diferentes, no seu ritmo.',ok:days.size>=3,icon:'clock'},{id:'balanced',title:'Dupla conquista',desc:'Acerte cinco questões diferentes de cada disciplina.',ok:['Português','Matemática'].every(s=>wins.filter(a=>(topic(a.topic)?.subject||a.subject)===s).length>=5),icon:'award'}]}
function nav(p){if(quiz||exam){modalConfirm('Pausar esta atividade?','O simulado ficará salvo para você continuar depois.',()=>{saveActive();quiz=null;exam=null;clearInterval(timer);page=p;render()});return}page=p;render();window.scrollTo(0,0)}
function saveActive(){if(demo)localStorage.setItem('tiradentes-active',JSON.stringify({quiz,exam}));else if(session)sessionStorage.setItem('tiradentes-active-'+user.id,JSON.stringify({quiz,exam}));}
function clearActive(){if(demo)localStorage.removeItem('tiradentes-active');else sessionStorage.removeItem('tiradentes-active-'+user.id)}
function activeSaved(){return demo?readStore('tiradentes-active',null):JSON.parse(sessionStorage.getItem('tiradentes-active-'+user.id)||'null')}
function shell(html){const admin=user?.role==='admin';$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">SUA PREPARAÇÃO</div><nav class="nav" aria-label="Menu principal">${[['dashboard','home','Meu painel'],['lessons','book','Minha trilha'],['simulators','test','Simulados'],['progress','chart','Evolução'],['rewards','award','Conquistas'],['guide','compass','Guia de ingresso'],...(admin||demo?[['admin','admin','Administração']]:[])].map(([p,i,t])=>`<button class="${page===p?'active':''} ${p==='admin'?'admin-nav':''}" data-page="${p}" ${page===p?'aria-current="page"':''}>${ico(i)}${t}</button>`).join('')}</nav><div class="sidebar-foot"><div class="side-note">${ico('spark')}<br><strong>Pequenos passos. Grandes planos.</strong><br>Aprender também é descobrir o que precisa de mais uma tentativa.</div><div class="profile"><span class="avatar">${demo?'EX':esc(user?.name?.slice(0,2).toUpperCase()||'AL')}</span><div><b>${demo?'Aluno de exemplo':esc(user?.name||'Estudante')}</b><small>${demo?'Demonstração interativa':'Acesso aprovado'}</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><span class="crumb">Preparação / ${esc({dashboard:'Meu painel',lessons:'Minha trilha',simulators:'Simulados',progress:'Evolução',rewards:'Conquistas',guide:'Guia de ingresso',admin:'Administração'}[page]||'Atividade')}</span><span class="mobile-brand">${ico('spark')}</span><div class="top-actions"><span class="pill">${ico('award')}${xp()} XP</span>${demo?'<span class="pill orange">Modo demonstração</span>':''}<button class="btn outline small" data-action="logout">${demo?'Sair da demo':'Sair'}</button></div></header><main id="main" tabindex="-1">${html}<p class="footer-note">Preparatório independente, sem vínculo institucional com a Brigada Militar. ${demo?'Seus exercícios ficam apenas neste navegador. Cadastros reais dependem da ativação do Supabase.':'Seu progresso é salvo na sua conta.'} Conteúdos de apoio não garantem aprovação.</p></main></div></div>`}
function heading(title,sub){return `<div class="heading"><div><div class="eyebrow">Um passo de cada vez</div><h1>${title}</h1><p>${sub}</p></div><span class="date">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'})}</span></div>`}
function mission(t,label){return `<div class="mission"><div class="tile-icon ${t.subject==='Português'?'purple':''}">${ico(t.subject==='Português'?'book':'chart')}</div><div class="body"><span class="pill ${t.subject==='Português'?'purple':''}">${esc(label||t.subject)}</span><h3>${esc(t.title)}</h3><p>${t.minutes} min · ${esc(status(t.id))}</p></div><button class="arrow" data-lesson="${t.id}" aria-label="Estudar ${esc(t.title)}">${ico('arrow')}</button></div>`}
function landing(){clearInterval(timer);$('#app').innerHTML=`<div class="landing"><nav>${brand()}<div class="nav-btns"><button class="btn outline small" data-auth="login">Entrar</button> <button class="btn small" data-auth="signup">Criar cadastro ${ico('arrow')}</button></div></nav><main id="main" style="padding:0"><section class="landing-hero"><div><div class="eyebrow">Preparatório · Colégio Tiradentes · RS</div><h1>Seu sonho tem<br>um <em>próximo passo.</em></h1><p>Descubra o que você já sabe. Fortaleça o que precisa. Prepare-se para o Tiradentes com aulas curtas, simulados e uma trilha feita a partir do seu desempenho.</p><div class="actions"><button class="btn" data-auth="signup">Quero começar ${ico('arrow')}</button>${C.demo?'<button class="btn outline" data-action="demo">Explorar demonstração</button>':''}</div><p style="font-size:12px">Cadastro → confirmação de e-mail → aprovação → sua preparação.</p></div><div class="landing-art">${art()}<div class="floating-note"><span class="pill">${ico('award')} Uma conquista por vez</span><p style="margin:10px 0 0">Cada dúvida vencida é um passo no seu caminho.</p></div></div></section><div class="landing-band"><div><strong>6 provas anteriores</strong><p>300 questões de 2020/21 a 2025/26, com gabaritos no banco.</p></div><div><strong>Português + Matemática</strong><p>Preparação alinhada aos conteúdos do edital.</p></div><div><strong>Aprender → praticar → revisar</strong><p>Feedback claro e conquistas por etapas vencidas.</p></div></div><div class="section-head"><h2>Uma preparação que acompanha você.</h2></div><div class="cards"><article class="course-card">${ico('compass')}<h3>Comece pelo diagnóstico</h3><p>O primeiro treino identifica dificuldades por habilidade. O que ainda não foi avaliado aparece como tal.</p></article><article class="course-card">${ico('book')}<h3>Aprenda em missões curtas</h3><p>Uma ideia, um exemplo resolvido e uma tentativa sua. Depois, retome o conteúdo com novos desafios.</p></article><article class="course-card">${ico('award')}<h3>Celebre o progresso</h3><p>Pontos por prática e conquistas por constância, recuperação de erros e etapas concluídas.</p></article></div><div class="notice spaced">${C.demo?'Versão de demonstração para avaliação. O cadastro real será ativado após configurar o banco independente do curso.':'O cadastro neste preparatório não substitui a inscrição no processo seletivo oficial.'}</div><button class="link" data-action="public-guide">Consultar edital e etapas de ingresso ${ico('arrow')}</button></main><footer>Missão Tiradentes · Preparatório independente para os Colégios Tiradentes da Brigada Militar do RS.<br>Sem vínculo com a instituição. Provas futuras podem mudar; acompanhe o edital oficial.</footer></div>`}
function dashboard(){let ev=evidence(),pr=priorities(),last=state.history.at(-1),tested=course.topics.filter(t=>metrics(t.id).n).length;let totalCorrect=ev.filter(a=>a.correct).length;let saved=activeSaved();const day=new Date().getDate();shell(`${heading(demo?'Olá, estudante 👋':`Olá, ${esc(user.name.split(' ')[0])} 👋`,'Seu próximo passo começa com o que você já sabe.')}<div class="dashboard-grid"><div><section class="hero"><div><div class="eyebrow">${state.history.length?'SUA PRÓXIMA MISSÃO':'VAMOS DESCOBRIR SEU PONTO DE PARTIDA'}</div><h2>${state.history.length?'Uma dúvida a menos.<br>Um passo mais perto.':'Seu caminho começa<br>com um diagnóstico.'}</h2><p>${state.history.length?`Sua trilha prioriza ${esc(pr[0]?.title.toLowerCase()||'as habilidades que faltam avaliar')}. Vamos aprender, praticar e voltar ao que importa.`:'Um treino sem pressão para descobrir suas forças e os conteúdos que merecem atenção.'}</p><button class="btn light" ${state.history.length?`data-lesson="${pr[0]?.id}"`:'data-action="diagnostic"'}>${state.history.length?'Continuar minha trilha':'Fazer meu diagnóstico'} ${ico('arrow')}</button></div><div class="hero-art">${art()}</div></section>${saved?'<div class="notice green spaced">Você tem uma atividade pausada. <button class="link" data-action="resume">Continuar de onde parei →</button></div>':''}<div class="stats"><div class="stat"><span>Último desempenho</span>${ico('chart')}<strong>${last?last.percent+'%':'—'}</strong><small>${last?esc(last.label):'Faça seu primeiro treino'}</small></div><div class="stat"><span>Habilidades avaliadas</span>${ico('compass')}<strong>${tested}<span> / ${course.topics.length}</span></strong><small>Sem estimativas para temas não avaliados</small></div><div class="stat"><span>Missões estudadas</span>${ico('book')}<strong>${state.lessons.length}</strong><small>${xp()} pontos de experiência</small></div></div><div class="section-head"><h2>Seu plano, no seu ritmo</h2><button class="link" data-page="lessons">Ver minha trilha →</button></div>${pr.slice(0,3).map(t=>mission(t,metrics(t.id).n&&metrics(t.id).rate<70?'Reforço recomendado':'Próximo passo')).join('')}<div class="section-head spaced"><h2>Treinar também faz parte</h2></div><div class="mission"><div class="tile-icon orange">${ico('test')}</div><div class="body"><h3>Simulado 2025/26</h3><p>50 questões no banco · 3 horas · recursos conferidos</p></div><button class="arrow" data-exam="2025-26" aria-label="Iniciar simulado 2025/26">${ico('arrow')}</button></div></div><aside class="dashboard-aside"><div class="panel calendar-panel"><div class="section-head"><h3>Seu ritmo de estudo</h3>${ico('clock')}</div><span class="muted" style="font-size:12px">${new Date().toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</span><div class="calendar">${['D','S','T','Q','Q','S','S'].map(d=>`<span class="day">${d}</span>`).join('')}${Array.from({length:new Date(new Date().getFullYear(),new Date().getMonth(),1).getDay()},()=>'<span></span>').join('')}${Array.from({length:new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()},(_,i)=>`<span class="num ${day===i+1?'today':''}">${i+1}</span>`).join('')}</div><p style="font-size:11px">Uma sessão pequena já conta. Não há punição por fazer uma pausa.</p><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Acertos em questões distintas</h3><div class="progress-ring" style="--p:${ev.length?totalCorrect/ev.length*100:0}%"><div><strong>${ev.length?Math.round(totalCorrect/ev.length*100)+'%':'—'}</strong><small>${ev.length?ev.length+' questões':'Ainda sem diagnóstico'}</small></div></div>${['Português','Matemática'].map(s=>{const a=ev.filter(x=>(topic(x.topic)?.subject||x.subject)===s),pct=a.length?Math.round(a.filter(x=>x.correct).length/a.length*100):0;return `<div class="track"><div class="track-label"><span>${s}</span><b>${a.length?pct+'%':'Não avaliado'}</b></div><div class="bar ${s==='Português'?'purple':''}"><span style="width:${pct}%"></span></div></div>`}).join('')}<span class="muted" style="font-size:10px">Indicador de prática, não previsão de aprovação.</span></div><div class="quote">${ico('spark')}<p>“Ainda não sei” é o começo de “agora entendi”.</p><small>Aprenda. Tente. Celebre. Repita.</small><button class="link" style="display:block;margin-top:20px;font-size:12px" data-page="rewards">Minhas conquistas →</button></div></aside></div>`)}
function lessons(){let filtered=priorities().filter(t=>(subject==='Todos'||t.subject===subject)&&t.title.toLowerCase().includes(query.toLowerCase()));shell(`${heading('Sua trilha de aprendizagem','Conteúdo curto. Exemplos claros. Prática com propósito.')}<div class="notice green">${state.history.length?'A ordem muda conforme suas respostas. Erros e respostas por palpite têm prioridade; temas ainda não avaliados entram antes dos conteúdos com bons resultados.':'Faça o diagnóstico para ordenar a trilha pelo seu desempenho. Você também pode começar por qualquer aula.'} O acervo inicial reúne 25 aulas de fundamentos; alguns tópicos avançados do edital ainda precisam de aprofundamento.</div><input class="search" aria-label="Buscar aula" placeholder="Buscar um conteúdo…" value="${esc(query)}" id="lesson-search"><div class="filters">${['Todos','Português','Matemática'].map(s=>`<button class="filter ${subject===s?'active':''}" data-subject="${s}">${s}</button>`).join('')}</div><div class="cards">${filtered.map(t=>`<article class="course-card"><span class="pill ${t.subject==='Português'?'purple':''}">${t.subject}</span><h3>${esc(t.title)}</h3><p>${esc(t.body.split('. ')[0])}.</p><div class="card-meta">${t.minutes} min · ${esc(status(t.id))}</div><button class="btn outline small" data-lesson="${t.id}">${state.lessons.includes(t.id)?'Revisar aula':'Estudar agora'} ${ico('arrow')}</button></article>`).join('')||'<div class="empty">Nenhuma aula encontrada. Tente outro termo.</div>'}</div>`)}
function lesson(id){const t=topic(id);if(!t)return;page='lessons';shell(`<div class="lesson"><button class="link" data-page="lessons">← Minha trilha</button><div class="spaced"><span class="pill ${t.subject==='Português'?'purple':''}">${t.subject} · ${t.minutes} min</span><h1 style="margin-top:18px">${esc(t.title)}</h1><p>Uma ideia de cada vez. Primeiro entenda; depois tente sem consultar.</p></div><div class="lesson-block"><div class="eyebrow">01 · ENTENDA A IDEIA</div><p>${esc(t.body)}</p></div><div class="lesson-block"><div class="eyebrow">02 · VEJA UM EXEMPLO</div><div class="example">${esc(t.example)}</div></div><div class="lesson-block"><div class="eyebrow">03 · FAÇA SUA TENTATIVA</div><p style="font-size:15px">Feche a explicação e tente recuperar a ideia. O erro é uma informação sobre o próximo passo.</p><button class="btn" data-practice="${t.id}">Praticar esta habilidade ${ico('arrow')}</button></div><p style="font-size:12px">${esc(t.trap)} A aula conta como estudada após sua tentativa, e não apenas pela abertura da página.</p></div>`)}
function simulators(){shell(`${heading('Simulados e treinos','Conheça a prova. Descubra suas dúvidas. Aprenda com cada tentativa.')}<section class="hero" style="min-height:190px;grid-template-columns:1fr auto"><div><div class="eyebrow">UM TREINO SEM PRESSÃO</div><h2>Diagnóstico de habilidades</h2><p>12 questões autorais · cerca de 25 minutos · sem cronômetro eliminatório. Uma amostra inicial, que melhora com mais prática.</p><button class="btn light" data-action="diagnostic">Iniciar diagnóstico ${ico('arrow')}</button></div><div class="hero-art" style="width:180px">${art()}</div></section><div class="section-head spaced"><h2>Provas anteriores, na íntegra</h2><span class="pill">6 edições · 300 questões</span></div><div class="cards">${course.exams.map(e=>`<article class="course-card"><span class="pill">Prova ${e.year.replace('-','/')}</span><h3>Simulado de ingresso ${e.year.slice(-2)}</h3><p>25 questões de Português e 25 de Matemática. Responda cada questão diretamente na tela, com os textos e figuras originais.</p><div class="card-meta">50 questões · 3 horas</div><div class="notice" style="margin:0;font-size:10px">${esc(e.status)}</div><button class="btn outline small" data-exam="${e.year}">Começar simulado ${ico('arrow')}</button></article>`).join('')}</div>`)}
function startQuiz(ids,kind='practice',lessonId=null){quiz={ids,index:0,answers:{},confidence:{},kind,lessonId,started:Date.now()};exam=null;results=null;saveActive();renderQuiz()}
function startDiagnostic(){let p=course.questions.filter(q=>topic(q.topic)?.subject==='Português'),m=course.questions.filter(q=>topic(q.topic)?.subject==='Matemática');const n=state.history.filter(h=>h.kind==='diagnostic').length;let pick=a=>Array.from({length:Math.min(6,a.length)},(_,i)=>a[(n*6+i)%a.length].id);startQuiz([...pick(p),...pick(m)],'diagnostic')}
function renderQuiz(){const q=course.questions.find(q=>q.id===quiz.ids[quiz.index]);if(!q){flash('Esta questão não está disponível.');quiz=null;render();return}const t=topic(q.topic),n=quiz.ids.length;page='simulators';shell(`<div class="lesson">${heading(quiz.kind==='diagnostic'?'Seu diagnóstico':'Sua tentativa',`${esc(t.title)} · Questão ${quiz.index+1} de ${n}`)}<div class="bar"><span style="width:${(quiz.index+1)/n*100}%"></span></div><div class="question-prompt">${esc(q.prompt)}</div><div class="options">${q.options.map((o,i)=>`<button class="option ${quiz.answers[q.id]===i?'selected':''}" data-answer="${i}" aria-pressed="${quiz.answers[q.id]===i}"><span class="letter">${'ABCDE'[i]}</span>${esc(o)}</button>`).join('')}</div><div class="confidence"><span>Como você chegou à resposta?</span><button class="${quiz.confidence[q.id]==='sure'?'selected':''}" data-confidence="sure">Entendi o caminho</button><button class="${quiz.confidence[q.id]==='guess'?'selected':''}" data-confidence="guess">Fiquei em dúvida</button></div><div class="quiz-footer"><button class="btn outline" data-action="quiz-prev" ${quiz.index===0?'disabled':''}>← Voltar</button><span class="saved">${demo?'Salvo neste navegador':'Atividade salva nesta sessão'}</span><button class="btn" data-action="quiz-next">${quiz.index===n-1?'Ver resultado':'Próxima questão'} ${ico('arrow')}</button></div><button class="link spaced" data-page="simulators">Pausar e continuar depois</button><p style="font-size:11px">${esc(q.source||'Exercício autoral alinhado ao edital')} · A resposta e a explicação aparecem ao concluir.</p></div>`)}
async function finishQuiz(){const qz=quiz;let items;try{if(demo){items=qz.ids.map(id=>{const q=course.questions.find(x=>x.id===id);return {id,topic:q.topic,selected:qz.answers[id]??null,correct:qz.answers[id]===q.answer,answer:q.answer,explanation:q.explanation,confidence:qz.confidence[id]||'guess',prompt:q.prompt,options:q.options}})}else{const r=await rpc('submit_practice',{p_answers:qz.ids.map(id=>({id,selected:qz.answers[id]??null,confidence:qz.confidence[id]||'guess'})),p_kind:qz.kind,p_lesson:qz.lessonId});items=r.items;}const correct=items.filter(a=>a.correct).length;const h={id:crypto.randomUUID(),kind:qz.kind,label:qz.kind==='diagnostic'?'Diagnóstico de habilidades':'Prática: '+topic(qz.lessonId||items[0].topic).title,date:new Date().toISOString(),items,percent:Math.round(correct/items.length*100)};state.history.push(h);if(qz.lessonId&&!state.lessons.includes(qz.lessonId))state.lessons.push(qz.lessonId);persist();quiz=null;clearActive();results=h;renderResults();notifyReward();}catch(e){flash(e.message)}}
function notifyReward(){for(const a of achievements())if(a.ok&&!state.rewards.includes(a.id)){state.rewards.push(a.id);flash('Conquista desbloqueada: '+a.title+' ✦')}persist()}
async function examAsset(year){if(demo)return `questoes/${year}.webp`;const r=await api(`/storage/v1/object/sign/questoes/${year}.webp`,{method:'POST',body:JSON.stringify({expiresIn:14400})});return C.supabaseUrl+'/storage/v1'+r.signedURL}
async function startExam(year){const e=course.exams.find(x=>x.year===year);if(!e)return;modalConfirm('Pronto para o simulado?','Você terá 3 horas. As questões aparecem diretamente na tela. Respostas em branco contam como erro; a correção segue o gabarito e as ressalvas da edição.',async()=>{try{const rows=demo?course.examQuestions.filter(q=>q.year===year):(await api('/rest/v1/exam_questions_public?select=data&year=eq.'+year+'&order=number.asc')).map(x=>x.data);if(rows.length!==50)throw Error('Esta edição ainda está em preparação.');exam={year,index:1,answers:{},deadline:Date.now()+3*60*60*1000,bank:rows,asset:await examAsset(year),assetCreated:Date.now()};quiz=null;saveActive();renderExam()}catch(err){flash(err.message)}})}
function questionVisual(q,regions,label){return regions.map((r,i)=>`<svg class="question-visual" viewBox="${r.join(' ')}" role="img" aria-label="${esc(label)}${regions.length>1?' · parte '+(i+1):''}" xmlns="http://www.w3.org/2000/svg"><title>${esc(label)}</title><image href="${esc(exam.asset)}" width="${q.atlas_width}" height="${q.atlas_height}"/></svg>`).join('')}
function renderExam(){const e=course.exams.find(x=>x.year===exam.year),q=exam.bank?.find(x=>x.number===exam.index);if(!q){flash('Retome o simulado pela lista de provas para carregar as questões.');exam=null;clearActive();simulators();return}page='simulators';shell(`${heading('Simulado '+e.year.replace('-','/'),'Uma questão por vez, diretamente na tela.')}<div class="notice">${esc(e.status)}. ${e.annulled?.length?'Questões anuladas recebem crédito e ficam fora do diagnóstico.':''}</div><div class="test-layout"><div><div class="page-nav"><button class="btn outline small" data-action="exam-prev" ${exam.index<=1?'disabled':''}>← Anterior</button><span>Questão ${exam.index} de 50</span><button class="btn outline small" data-action="exam-next" ${exam.index>=50?'disabled':''}>Próxima →</button></div><article class="panel question-panel"><span class="pill">${esc(q.subject)} · Questão ${q.number}</span>${q.stimulus.length?`<details class="question-passage" open><summary>Texto de apoio</summary>${questionVisual(q,q.stimulus,'Texto de apoio da questão '+q.number)}</details>`:''}<div class="question-body">${questionVisual(q,q.body,'Enunciado e alternativas da questão '+q.number)}</div><details class="question-text"><summary>Texto extraído para apoio à leitura</summary><p>Fórmulas e figuras devem ser conferidas na imagem original acima.</p><pre>${esc(q.original_text)}</pre></details><h3 style="margin-top:24px">Marque sua resposta</h3><div class="exam-options">${[...'ABCDE'].map((a,i)=>`<button class="${exam.answers[exam.index]===a?'selected':''}" data-exam-answer="${a}" aria-pressed="${exam.answers[exam.index]===a}" aria-label="Alternativa ${a}${q.options[i]?': '+esc(q.options[i]):''}">${a}</button>`).join('')}</div><button class="link" data-action="exam-clear">Limpar resposta</button></article></div><aside class="panel"><div class="eyebrow">TEMPO RESTANTE</div><div class="timer" id="timer">03:00:00</div><p style="font-size:11px" id="answered-count">${Object.keys(exam.answers).length} de 50 respondidas</p><h3>Seu cartão de respostas</h3><div class="answer-grid">${Array.from({length:50},(_,i)=>`<button class="${exam.answers[i+1]?'answered':''} ${exam.index===i+1?'current':''}" data-exam-index="${i+1}" aria-label="Questão ${i+1}${exam.answers[i+1]?', respondida '+exam.answers[i+1]:', não respondida'}">${i+1}</button>`).join('')}</div><button class="btn" style="width:100%" data-action="exam-finish">Finalizar simulado</button><button class="link spaced" style="font-size:12px" data-page="simulators">Pausar visualização</button><p style="font-size:10px">O tempo continua durante a pausa para reproduzir a duração da prova.</p></aside></div>`);clearInterval(timer);tick();timer=setInterval(tick,1000)}
function tick(){if(!exam)return;const sec=Math.max(0,Math.ceil((exam.deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=[Math.floor(sec/3600),Math.floor(sec%3600/60),sec%60].map(n=>String(n).padStart(2,'0')).join(':');if(!sec){clearInterval(timer);finishExam()}}
async function finishExam(){if(!exam||exam.submitting)return;exam.submitting=true;const e=course.exams.find(x=>x.year===exam.year);try{let items;if(demo)items=Array.from({length:50},(_,i)=>{const n=i+1,annulled=e.annulled.includes(n);return {id:e.year+'-'+n,number:n,topic:e.topics[i],subject:n<=25?'Português':'Matemática',selected:exam.answers[n]??null,answer:e.answers[i],correct:annulled||exam.answers[n]===e.answers[i],annulled}});else items=(await rpc('submit_exam',{p_year:exam.year,p_answers:exam.answers})).items;const h={id:crypto.randomUUID(),kind:'exam',label:'Prova '+exam.year.replace('-','/'),date:new Date().toISOString(),items,percent:items.filter(x=>x.correct).length*2};state.history.push(h);persist();clearInterval(timer);exam=null;clearActive();results=h;renderResults();notifyReward()}catch(e){exam.submitting=false;flash(e.message)}}
function renderResults(){const h=results;if(!h){render();return}const valid=h.items.filter(a=>!a.annulled),isExam=h.kind==='exam';const p=priorities();shell(`${heading('Cada tentativa mostra um caminho.','Confira o resultado e use o feedback no próximo passo.')}<div class="panel results-top"><span class="pill">${esc(h.label)}</span><strong>${h.percent}${isExam?'<span style="font-size:24px"> / 100</span>':'%'}</strong><p>${h.items.filter(x=>x.correct&&!x.annulled).length} acertos em ${valid.length} questões válidas.${isExam&&h.items.some(x=>x.annulled)?' A nota inclui crédito das questões anuladas.':''} ${valid.filter(x=>x.selected===null).length} em branco.</p><button class="btn" data-page="lessons">Ver minha trilha ajustada ${ico('arrow')}</button></div><div class="section-head spaced"><h2>Seu próximo passo</h2></div>${p.slice(0,2).map(t=>mission(t)).join('')}<div class="panel spaced"><h3>${isExam?'Cartão de correção':'Entenda suas respostas'}</h3>${isExam?`<table class="table"><thead><tr><th>Questão</th><th>Sua resposta</th><th>Gabarito</th><th>Resultado</th><th>Estudar</th></tr></thead><tbody>${h.items.map(a=>`<tr><td>${a.number}</td><td>${esc(a.selected||'Em branco')}</td><td>${a.annulled?'Anulada':a.answer}</td><td>${a.annulled?'Crédito geral':a.correct?'✓ Acerto':'Revisar'}</td><td>${a.topic&&!a.annulled?`<button class="link" data-lesson="${a.topic}">${esc(topic(a.topic)?.title)} →</button>`:'—'}</td></tr>`).join('')}</tbody></table><p style="font-size:12px">As cinco edições mais antigas têm correção por disciplina; a classificação por habilidade está disponível na prova 2025/26. Consulte as ressalvas do gabarito na página de simulados.</p>`:h.items.map((a,i)=>`<div class="lesson-block"><span class="pill ${a.correct?'':'orange'}">${a.correct?'✓ Acerto':'Revisão'} · ${esc(topic(a.topic)?.title)}</span><h3 class="spaced">${i+1}. ${esc(a.prompt)}</h3><p style="font-size:13px">Sua resposta: ${a.selected===null?'Em branco':esc(a.options[a.selected])}<br>Resposta esperada: <b>${esc(a.options[a.answer])}</b></p><div class="example" style="font-size:14px">${esc(a.explanation)}</div><button class="link spaced" data-lesson="${a.topic}">Estudar esta habilidade →</button></div>`).join('')}</div>`)}
function progress(){shell(`${heading('Veja o quanto você avançou.','O diagnóstico fica mais confiável com questões diferentes e novas tentativas.')}<div class="notice green">Acertos e erros são contabilizados por questão distinta, usando a tentativa mais recente. Repetir a mesma questão não aumenta o número de evidências. Pelo menos três questões distintas e 80% de acerto indicam consolidação inicial; isso não certifica domínio do edital.</div><div class="panel"><h3>Mapa de habilidades</h3><table class="table"><thead><tr><th>Habilidade</th><th>Evidências</th><th>Acertos</th><th>Próximo passo</th></tr></thead><tbody>${course.topics.map(t=>{const m=metrics(t.id);return `<tr><td><button class="link" data-lesson="${t.id}">${esc(t.title)}</button></td><td>${m.n} questões</td><td>${m.rate===null?'—':m.rate+'%'}</td><td>${esc(status(t.id))}</td></tr>`}).join('')}</tbody></table></div><div class="section-head spaced"><h2>Seu histórico</h2><button class="link" data-action="export">Exportar meu progresso ↓</button></div><div class="panel">${state.history.length?[...state.history].reverse().map(h=>`<div class="history-item"><div><b>${esc(h.label)}</b><p style="font-size:11px;margin:5px 0">${new Date(h.date).toLocaleString('pt-BR')} · ${h.items.length} questões</p></div><b>${h.percent}%</b><button class="link" data-result="${h.id}">Rever →</button></div>`).join(''):'<div class="empty">Seu histórico começa com o primeiro diagnóstico.<br><button class="btn spaced" data-action="diagnostic">Começar agora</button></div>'}</div>`)}
function rewards(){const x=xp(),level=Math.floor(x/150)+1;const badges=achievements();shell(`${heading('Seu esforço merece uma conquista.','Pontos por aprender. Marcos por avançar. Sem competição entre alunos.')}<div class="hero" style="min-height:220px"><div><div class="eyebrow">SEU CAMINHO DE CONQUISTAS</div><h2>Nível ${level} · ${['Explorador','Aprendiz','Desbravador','Estrategista'][Math.min(level-1,3)]}</h2><p>${x} XP conquistados. Faltam ${150-x%150} XP para o próximo nível.</p><div class="bar" style="background:#3f6052"><span style="width:${x%150/150*100}%;background:var(--lime)"></span></div></div><div class="hero-art">${art()}</div></div><div class="section-head spaced"><h2>Etapas vencidas</h2><span class="pill">${badges.filter(a=>a.ok).length} de ${badges.length}</span></div><div class="cards">${badges.map(a=>`<article class="course-card" style="${a.ok?'border-color:#7a9869;background:#f0f5e9':''}"><div class="tile-icon ${a.ok?'':'orange'}">${ico(a.icon)}</div><span class="pill ${a.ok?'':'orange'}">${a.ok?'Desbloqueada ✓':'Sua próxima conquista'}</span><h3>${a.title}</h3><p>${a.desc}</p></article>`).join('')}</div><div class="panel spaced"><h3>Como seus pontos funcionam</h3><p>+10 XP pelo primeiro acerto em cada questão distinta; +15 XP por aula estudada e praticada, uma vez; +20 XP por habilidade em que você recuperou um erro; +50 XP por edição de prova inteiramente respondida, uma vez. Os XP conquistados permanecem com você. Novos erros ajudam a ajustar a trilha sem retirar suas conquistas.</p><p>Conquistas são simbólicas nesta versão. Prêmios materiais ou benefícios pagos ainda não foram configurados. Não há ranking público, perda de sequência ou punição por pausas.</p></div>`)}
const source2027='https://www.brigadamilitar.rs.gov.br/upload/arquivos/202608/24130956-edital-202-dec-det-2026-colegio-tiradentes-2027.pdf';
function guideHtml(){return `${heading('O ingresso vai além da prova.','Orientações para o aluno e para quem acompanha sua preparação.')}<div class="notice green">Referência: edital nº 202/DEC-DET/2026, para ingresso em 2027. Conferido em 12/10/2026. Consulte os aditamentos para locais, horários e alterações. <a class="link" href="${source2027}" target="_blank" rel="noopener">Ler edital oficial ↗</a></div><div class="cards"><article class="course-card"><span class="pill">01 · Exame intelectual</span><h3>Português e Matemática</h3><p>50 questões, 25 por disciplina, 2 pontos por questão e duração de 3 horas. Zerar uma disciplina elimina o candidato. Não há redação ou outras disciplinas nesta prova.</p></article><article class="course-card"><span class="pill orange">02 · Exame de saúde</span><h3>Documentação médica</h3><p>Etapa eliminatória. A ficha prevista no edital deve ser preenchida pelos responsáveis e pelo médico, com a declaração de aptidão exigida.</p></article><article class="course-card"><span class="pill purple">03 · Exame físico</span><h3>Apoio, abdominal e corrida</h3><p>Etapa eliminatória com flexão de braços, abdominal e corrida de 12 minutos. O anexo B define execução e índices. A preparação física precisa de acompanhamento profissional adequado.</p></article></div><div class="panel spaced"><h3>Checklist para organizar o ingresso</h3>${['Ler o edital e conferir requisitos de idade e escolaridade','Conferir inscrição e homologação no processo seletivo oficial','Verificar local e horário nos aditamentos da unidade escolhida','Organizar documento de identidade e material permitido','Providenciar ficha médica conforme convocação','Conferir regras e índices do exame físico no anexo B','Conferir documentos e prazos de matrícula','Participar da semana de adaptação prevista após a matrícula'].map((s,i)=>`<label style="display:flex;gap:12px;align-items:flex-start;padding:13px 0;border-bottom:1px solid var(--line);font-size:13px;line-height:1.7"><input type="checkbox" data-check="${i}" ${state.checks.includes(i)?'checked':''}>${s}</label>`).join('')}</div><div class="panel spaced"><h3>Fontes e limites do conteúdo</h3><ul class="source-list"><li><a href="https://www.brigadamilitar.rs.gov.br/processo-seletivo-da-rede-dos-colegios-tiradentes-da-brigada-militar-para-o-ano-letivo-de-2027" target="_blank" rel="noopener">Página oficial do ingresso 2027 e aditamentos</a></li><li><a href="https://www.brigadamilitar.rs.gov.br/colegio-tiradentes-2026" target="_blank" rel="noopener">Ingresso 2026: edital, gabarito e recursos</a></li><li><a href="https://www.brigadamilitar.rs.gov.br/colegio-tiradentes-2025" target="_blank" rel="noopener">Ingresso 2025: edital e aditamentos</a></li><li><a href="https://www.brigadamilitar.rs.gov.br/colegios-tiradentes-2024" target="_blank" rel="noopener">Ingresso 2024: edital e aditamentos</a></li><li><a href="https://educationendowmentfoundation.org.uk/news/eef-blog-why-bother-with-retrieval" target="_blank" rel="noopener">EEF: recuperação ativa do conhecimento</a></li><li><a href="https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/feedback" target="_blank" rel="noopener">EEF: feedback para aprendizagem</a></li></ul><p style="font-size:12px">As aulas e os exercícios novos são autorais, alinhados ao edital. São material de estudo, sem previsão garantida de questões futuras. O diagnóstico é uma regra pedagógica transparente e não um teste psicométrico validado.</p><p style="font-size:12px">Acervo inicial fornecido pelo responsável pelo projeto: seis provas e seis gabaritos. As edições 2021/22 e 2022/23 têm gabaritos de fonte secundária. Em 2025/26, as questões 13 e 40 foram anuladas após recursos.</p></div>`}
function guide(){shell(guideHtml())}
async function admin(){page='admin';if(!demo&&user?.role!=='admin'){flash('Apenas o administrador pode acessar esta área.');nav('dashboard');return}let rows;if(demo)rows=[{id:'example',name:'Aluno de exemplo',email:'Dados fictícios',status:adminDemo}];else try{rows=await api('/rest/v1/profiles?select=id,name,email,status,created_at&role=eq.student&order=created_at.desc')}catch(e){flash(e.message);return}shell(`${heading('Acesso com aprovação.','O administrador decide quem pode acessar o curso e os simulados.')} ${demo?'<div class="notice">Ambiente de teste. A solicitação abaixo é fictícia e não cria uma conta real. As decisões valem apenas nesta demonstração.</div>':''}<div class="panel"><h3>Solicitações de cadastro</h3>${rows.length?rows.map(r=>`<div class="admin-row"><b>${esc(r.name)}</b><p style="font-size:12px;margin:5px 0">${esc(r.email)} · ${esc({pending:'Aguardando aprovação',approved:'Aprovado',rejected:'Não aprovado',suspended:'Suspenso'}[r.status])}</p><div class="actions">${r.status!=='approved'?`<button class="btn small" data-approve="${r.id}">Aprovar acesso</button>`:''}${r.status==='pending'?`<button class="btn outline small" data-reject="${r.id}">Não aprovar</button>`:''}${r.status==='approved'?`<button class="btn outline small" data-suspend="${r.id}">Suspender</button>`:''}</div></div>`).join(''):'<div class="empty">Nenhuma solicitação recebida.</div>'}</div><div class="panel spaced"><h3>Fluxo de acesso</h3><p>Cadastro → confirmação do e-mail → aguardando aprovação → acesso autorizado. A decisão de aprovação é validada no banco; o aluno não pode alterar seu próprio status ou papel.</p>${demo?'<button class="link" data-action="preview-pending">Ver tela de cadastro pendente →</button>':''}</div>`)}
function render(){if(!demo&&!user){landing();return}if(quiz){renderQuiz();return}if(exam){renderExam();return}({dashboard,lessons,simulators,progress,rewards,guide,admin}[page]||dashboard)()}
function auth(mode){const ready=!!(C.supabaseUrl&&C.supabaseAnonKey);const html=`<div class="modal-head"><h2>${mode==='signup'?'Seu primeiro passo':mode==='reset'?'Recuperar acesso':'Que bom ter você aqui.'}</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><p>${mode==='signup'?'Crie seu cadastro. Após confirmar o e-mail, aguarde a aprovação do administrador.':mode==='reset'?'Enviaremos um link para você definir uma nova senha.':'Entre para continuar sua preparação.'}</p>${!ready?'<div class="notice">O cadastro real ainda não está ativo. Estamos preparando o banco independente do curso. Você pode explorar a demonstração sem informar dados pessoais.</div>':''}<form class="form" id="auth-form" data-mode="${mode}">${mode==='signup'?'<label for="name">Nome do aluno</label><input id="name" name="name" required maxlength="80" autocomplete="name"><label for="unit">Unidade pretendida</label><select id="unit" name="unit"><option>Pelotas</option><option>Porto Alegre</option><option>Passo Fundo</option><option>Santa Maria</option><option>Ijuí</option><option>Santo Ângelo</option><option>São Gabriel</option><option>Caxias do Sul</option></select>':''}<label for="email">E-mail ${mode==='signup'?'de contato do responsável':''}</label><input id="email" name="email" type="email" required autocomplete="email">${mode!=='reset'?'<label for="password">Senha</label><input id="password" name="password" type="password" required minlength="10" autocomplete="'+(mode==='signup'?'new-password':'current-password')+'">':''}${mode==='signup'?'<label class="check"><input name="consent" type="checkbox" required>Sou responsável pelo aluno ou tenho autorização do responsável para este cadastro e o armazenamento do progresso de estudo.</label>':''}<button class="btn" type="submit" ${ready?'':'disabled'}>${mode==='signup'?'Criar cadastro':mode==='reset'?'Enviar link':'Entrar'}</button><div class="form-msg" role="status" id="auth-msg"></div></form><div style="display:flex;justify-content:space-between;gap:15px;margin-top:18px;font-size:12px"><button class="link" data-auth="${mode==='signup'?'login':'signup'}">${mode==='signup'?'Já tenho cadastro':'Criar cadastro'}</button>${mode==='login'?'<button class="link" data-auth="reset">Esqueci minha senha</button>':''}</div>${C.demo?'<button class="link spaced" data-action="demo">Explorar demonstração →</button>':''}`;openModal(html)}
function openModal(html){$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function modalConfirm(title,text,callback){openModal(`<div class="modal-head"><h2>${title}</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><p>${text}</p><div class="quiz-footer"><button class="btn outline" data-action="close-modal">Voltar</button><button class="btn" id="confirm-modal">Continuar ${ico('arrow')}</button></div>`);$('#confirm-modal').onclick=()=>{$('#modal').close();callback()}}
async function api(path,opts={},refresh=true){if(!C.supabaseUrl||!C.supabaseAnonKey)throw Error('O cadastro real ainda não foi ativado.');let r=await fetch(C.supabaseUrl+path,{...opts,headers:{apikey:C.supabaseAnonKey,'Content-Type':'application/json',...(session?.access_token?{Authorization:'Bearer '+session.access_token}:{}),...opts.headers}});if(r.status===401&&session?.refresh_token&&refresh){const s=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})},false);session=s;sessionStorage.setItem('tiradentes-session',JSON.stringify(s));return api(path,opts,false)}const t=await r.text();const data=t?JSON.parse(t):null;if(!r.ok)throw Error(data?.msg||data?.message||data?.error_description||'Não foi possível completar a operação.');return data}
const rpc=(name,body)=>api('/rest/v1/rpc/'+name,{method:'POST',body:JSON.stringify(body)});
async function loadAccount(){const u=await api('/auth/v1/user');const p=await api('/rest/v1/profiles?id=eq.'+u.id+'&select=*');user=p[0];if(!user)throw Error('Não foi possível encontrar o cadastro.');if(user.status!=='approved'){pending();return}const [ts,qs,es,hs,ls]=await Promise.all([api('/rest/v1/topics?select=data'),api('/rest/v1/questions_public?select=*'),api('/rest/v1/exams_public?select=*'),api('/rest/v1/attempts?select=data&user_id=eq.'+u.id+'&order=created_at.asc'),api('/rest/v1/lesson_progress?select=topic_id&user_id=eq.'+u.id)]);course={topics:ts.map(x=>x.data),questions:qs,exams:es};state={...emptyState(),history:hs.map(x=>x.data),lessons:ls.map(x=>x.topic_id)};render()}
function pending(){clearInterval(timer);user=null;landing();openModal(`<div class="modal-head"><h2>Cadastro recebido.</h2><button data-action="close-modal" aria-label="Fechar">×</button></div><span class="pill orange">Aguardando aprovação</span><p>Após a confirmação do seu e-mail, o administrador poderá liberar o acesso. Enquanto isso, o curso e os simulados permanecem bloqueados.</p><button class="btn" data-action="recheck">Verificar meu acesso</button>`)}
async function enterDemo(){if(!C.demo)return;$('#modal').close();if(!window.COURSE){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='content.js';s.onload=resolve;s.onerror=reject;document.head.append(s)})}course=window.COURSE;demo=true;sessionStorage.setItem('tiradentes-demo-open','1');state=readStore('tiradentes-demo-v1',emptyState());page='dashboard';render()}
async function authSubmit(e){e.preventDefault();const form=e.target;if(form.id!=='auth-form')return;const f=new FormData(form),mode=form.dataset.mode,btn=form.querySelector('button[type=submit]');btn.disabled=true;$('#auth-msg').textContent='Um instante…';try{if(mode==='signup'){await api('/auth/v1/signup?redirect_to='+encodeURIComponent(location.origin+location.pathname),{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password'),data:{name:f.get('name'),unit:f.get('unit'),guardian_consent:true}})});form.reset();$('#auth-msg').textContent='Cadastro enviado. Confirme seu e-mail e aguarde a aprovação do administrador.'}else if(mode==='reset'){await api('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+location.pathname),{method:'POST',body:JSON.stringify({email:f.get('email')})});$('#auth-msg').textContent='Se houver uma conta com este e-mail, você receberá um link de recuperação.'}else{session=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});sessionStorage.setItem('tiradentes-session',JSON.stringify(session));demo=false;$('#modal').close();await loadAccount()}}catch(err){const m=err.message;$('#auth-msg').textContent=/not authorized|email_address_not_authorized/i.test(m)?'O envio de confirmação ainda está em configuração. Tente novamente após a liberação pelo administrador.':/invalid login credentials/i.test(m)?'E-mail ou senha incorretos. Confira os dados e tente novamente.':/email not confirmed/i.test(m)?'Confirme seu e-mail antes de entrar.':/email rate limit|over_email_send_rate_limit/i.test(m)?'O limite temporário de envio foi atingido. Aguarde antes de tentar novamente.':m;$('#auth-msg').classList.add('error')}finally{btn.disabled=false}}
document.addEventListener('submit',authSubmit);
document.addEventListener('input',e=>{if(e.target.id==='lesson-search'){query=e.target.value;const pos=e.target.selectionStart;lessons();$('#lesson-search').focus();$('#lesson-search').setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){let n=Number(e.target.dataset.check);state.checks=e.target.checked?[...new Set([...state.checks,n])]:state.checks.filter(x=>x!==n);persist()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;if(!Object.keys(d).length)return;if(b.tagName==='A')e.preventDefault();try{
if(d.page){nav(d.page);return}if(d.auth){auth(d.auth);return}if(d.subject){subject=d.subject;lessons();return}if(d.lesson){if(quiz||exam){nav('lessons');return}lesson(d.lesson);return}if(d.practice){const ids=course.questions.filter(q=>q.topic===d.practice).map(q=>q.id);startQuiz(ids,'practice',d.practice);return}if(d.result){results=state.history.find(h=>h.id===d.result);renderResults();return}if(d.exam){startExam(d.exam);return}
if(d.answer!==undefined&&quiz){quiz.answers[quiz.ids[quiz.index]]=Number(d.answer);saveActive();renderQuiz();return}if(d.confidence&&quiz){quiz.confidence[quiz.ids[quiz.index]]=d.confidence;saveActive();renderQuiz();return}if(d.examAnswer&&exam){exam.answers[exam.index]=d.examAnswer;saveActive();renderExam();return}if(d.examIndex&&exam){exam.index=Number(d.examIndex);const ex=course.exams.find(x=>x.year===exam.year),p=ex.pages.findIndex(ns=>ns.includes(exam.index));if(p>=0)exam.page=p+1;saveActive();renderExam();return}
if(d.approve||d.reject||d.suspend){const id=d.approve||d.reject||d.suspend,status=d.approve?'approved':d.reject?'rejected':'suspended';if(demo)adminDemo=status;else await rpc('set_access',{p_user:id,p_status:status});flash(status==='approved'?'Acesso aprovado.':'Status atualizado.');await admin();return}
switch(d.action){case'home':if(demo||user)nav('dashboard');else landing();break;case'demo':await enterDemo();break;case'close-modal':$('#modal').close();break;case'logout':saveActive();clearInterval(timer);if(session)await api('/auth/v1/logout',{method:'POST'}).catch(()=>{});quiz=null;exam=null;user=null;demo=false;session=null;state=emptyState();sessionStorage.removeItem('tiradentes-session');sessionStorage.removeItem('tiradentes-demo-open');landing();break;case'diagnostic':startDiagnostic();break;case'quiz-prev':quiz.index--;saveActive();renderQuiz();break;case'quiz-next':if(quiz.answers[quiz.ids[quiz.index]]===undefined){flash('Escolha uma alternativa antes de continuar.');return}if(quiz.index<quiz.ids.length-1){quiz.index++;saveActive();renderQuiz()}else await finishQuiz();break;case'exam-prev':exam.index--;saveActive();renderExam();break;case'exam-next':exam.index++;saveActive();renderExam();break;case'exam-clear':delete exam.answers[exam.index];saveActive();renderExam();break;case'exam-finish':modalConfirm('Finalizar este simulado?',`Você respondeu ${Object.keys(exam.answers).length} de 50 questões. As restantes ficarão em branco.`,finishExam);break;case'resume':{const a=activeSaved();if(a){quiz=a.quiz;exam=a.exam;if(exam){exam.asset=await examAsset(exam.year);exam.assetCreated=Date.now()}render()}break}case'export':{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),history:state.history,lessons:state.lessons},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='meu-progresso-tiradentes.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);break}case'preview-pending':openModal('<div class="modal-head"><h2>Cadastro recebido.</h2><button data-action="close-modal">×</button></div><span class="pill orange">Aguardando aprovação · exemplo</span><p>Seu cadastro foi recebido. Confirme seu e-mail e aguarde a liberação do administrador.</p><p>Curso e simulados bloqueados até a aprovação.</p>');break;case'recheck':$('#modal').close();await loadAccount();break;case'public-guide':openModal('<div class="modal-head"><h2>Guia de ingresso</h2><button data-action="close-modal">×</button></div><p>A prova cobra Português e Matemática. Há também exames de saúde e físico, além da matrícula e adaptação.</p><p><a class="link" href="'+source2027+'" target="_blank" rel="noopener">Ler edital oficial 2027 ↗</a></p>');break;
}}catch(err){flash(err.message)}});
async function boot(){try{const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('access_token')){session={access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token')};sessionStorage.setItem('tiradentes-session',JSON.stringify(session));history.replaceState(null,'',location.pathname);if(hash.get('type')==='recovery'){landing();openModal('<h2>Definir nova senha</h2><form class="form" id="new-password"><label>Nova senha<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><button class="btn">Salvar senha</button></form>');$('#new-password').onsubmit=async e=>{e.preventDefault();try{await api('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:new FormData(e.target).get('password')})});$('#modal').close();await loadAccount()}catch(err){flash(err.message)}};return}}else session=JSON.parse(sessionStorage.getItem('tiradentes-session')||'null');if(session&&C.supabaseUrl){await loadAccount();return}if(C.demo&&sessionStorage.getItem('tiradentes-demo-open')==='1'){await enterDemo();return}landing()}catch(e){user=null;landing();flash(e.message)}}
boot();
